package com.gamehub.application.controller; import com.gamehub.application.UserService; import com.gamehub.infrastructure.CustomerRepository; import com.gamehub.application.service.AccountService; import com.gamehub.domain.Role; import com.gamehub.domain.User; import java.util.List; public final class AccountController {private final AccountService service; private final UserService users; public AccountController(UserService users,CustomerRepository customers){this.users=users;this.service=new AccountService(users,customers);}public User authenticate(String l,String p)throws Exception{return service.authenticate(l,p);}public User register(String n,String e,String ph,String p,String c)throws Exception{return service.register(n,e,ph,p,c);}public User provision(User actor,String username,String password,Role role)throws Exception{return users.provision(actor,username,password,role);}public List<String> customers(long actor)throws Exception{return service.customers(actor);}}

